custom_css_content:
/* kaf-cli 預設樣式 */
body {
    margin: 1.5em;
    font-family: -apple-system, BlinkMacSystemFont, "PingFang TC", "Microsoft JhengHei", "Noto Sans TC", sans-serif;
}

h2.volume {
    text-align: center;
    border-top: 3px double #555;
    border-bottom: 3px double #555;
    padding: 10px 0;
    margin: 2em 0 1.5em 0;
    color: #333;
}

h3.title {
    text-align: center;
    font-size: 1.35em;
    margin: 1.8em 0 1em 0;
    font-weight: bold;
}

h3.title span.chapter-number {
    color: #666;
    margin-right: 0.5em;
}

.content {
    text-indent: 2em;
    line-height: 1.6;
    margin-bottom: 0.8em;
    text-align: justify;
    word-break: break-all;
}
